<div><form wire:submit="{{ $editingEntryId === null ? 'save' : 'update' }}"><input wire:model="title" placeholder="Schedule title"><input wire:model="starts_at" type="datetime-local"><input wire:model="ends_at" type="datetime-local"><input wire:model="recurrence_type" placeholder="daily, weekly, monthly"><input wire:model="recurrence_value" type="number" min="1"><button type="submit">{{ $editingEntryId === null ? 'Schedule' : 'Update schedule' }}</button>@if ($editingEntryId !== null)<button type="button" wire:click="cancelEdit">Cancel</button>@endif</form>@error('starts_at')<p>{{ $message }}</p>@enderror<ul>@forelse($entries as $entry)<li>{{ $entry->title }} — {{ $entry->starts_at }} ({{ $entry->status }}) @if ($entry->next_due_at)Next due {{ $entry->next_due_at }} @endif <button type="button" wire:click="edit({{ $entry->id }})">Edit</button> @if ($entry->status === 'scheduled')<button type="button" wire:click="transition({{ $entry->id }}, 'in_progress')">Start</button>@elseif ($entry->status === 'in_progress')<button type="button" wire:click="transition({{ $entry->id }}, 'completed')">Complete</button>@endif <button type="button" wire:click="delete({{ $entry->id }})">Delete</button></li>@empty<li>No schedule entries yet.</li>@endforelse</ul></div>
